import { Table, type TableColumn, type TableRow } from '@design-schema/react';

interface Invoice extends TableRow {
  customer: string;
  status: string;
  amount: number;
  due: string;
}

const DATA: Invoice[] = [
  { id: 'inv-1001', customer: 'Aster Studio', status: 'Open', amount: 420, due: '2026-09-30' },
  { id: 'inv-1002', customer: 'Bramble & Co', status: 'Overdue', amount: 1280, due: '2026-08-15' },
  { id: 'inv-1003', customer: 'Cedar Analytics', status: 'Open', amount: 96, due: '2026-10-04' },
  { id: 'inv-1004', customer: 'Driftwood Supply', status: 'Paid', amount: 640, due: '2026-09-01' },
];

const COLUMNS: TableColumn[] = [
  { key: 'customer', header: 'Customer', isRowHeader: true },
  { key: 'status', header: 'Status' },
  {
    key: 'amount',
    header: 'Amount (USD)',
    abbr: 'Amount',
    align: 'end',
    sortable: true,
    render: (row) => `$${(row as Invoice).amount.toFixed(2)}`,
  },
  { key: 'due', header: 'Due date', hideBelow: 'prose' },
];

<Table caption="Open invoices" columns={COLUMNS} data={DATA} />

snippets.lit:
import '@design-schema/lit';
import { html } from 'lit';
import type { TableColumn, TableRow, TableRowPressDetail, TableSelectionChangeDetail, TableSortChangeDetail } from '@design-schema/lit';

const invoiceColumns: TableColumn[] = [
  { key: 'id', header: 'Invoice', isRowHeader: true },
  { key: 'customer', header: 'Customer' },
  { key: 'amount', header: 'Amount (USD)', align: 'end', sortable: true },
  { key: 'status', header: 'Status', hideBelow: 'content' },
];

const invoiceRows: TableRow[] = [
  { id: 'INV-1001', customer: 'Acme Co.', amount: '$1,240.00', status: 'Open' },
  { id: 'INV-1002', customer: 'Globex', amount: '$860.50', status: 'Open' },
  { id: 'INV-1003', customer: 'Initech', amount: '$3,020.00', status: 'Overdue' },
  { id: 'INV-1004', customer: 'Umbrella Corp.', amount: '$412.75', status: 'Paid' },
];

html`
    <ds-table
      caption="Open invoices"
      .columns=${invoiceColumns}
      .data=${invoiceRows}
      empty-message=""
      @sort-change=${(event: CustomEvent<TableSortChangeDetail>) => console.log('sort-change', event.detail)}
      @selection-change=${(event: CustomEvent<TableSelectionChangeDetail>) =>
  console.log('selection-change', event.detail)}
      @row-press=${(event: CustomEvent<TableRowPressDetail>) => console.log('row-press', event.detail)}
    ></ds-table>
`;

